import sys
sys.path.insert(0,'scripts')
from build_library import *
if (DEST/"security-review-log.json").exists():
 raise SystemExit("Review already applied")
changes=[]
def edit(j,i,**kw):
 p=DEST/'results'/f'{j}.json';r=read(p);b=DEST/'before-security-review'/p.name
 if not b.exists():write(b,r)
 c=r['cards'][i];old=c['title'];c.update(kw);c['id']=card_id(c['source_id'],{k:c[k] for k in ['title','summary','use_when','steps','caveats','tags']});validate_cards({'cards':r['cards']});write(p,r);changes.append({'job':j,'index':i,'before':old,'after':c['title']})
edit('a19f25237e92e2bfad8b283b',10,title='Separate malware detection from checkout fraud scoring',summary='Use endpoint and site protection for malicious code, and payment/order risk tools for suspicious transactions.',steps=['Inventory storefront scripts, integrations and administrative devices exposed to malicious code.','Use appropriate malware detection and patching on systems the merchant controls; a hosted storefront may restrict direct scanning or installation.','Use payment-provider or fraud-platform risk signals to triage suspicious orders; antivirus software is not generally an order-fraud scoring system.','Route uncertain high-risk orders for review and track false positives alongside fraud loss.','Investigate both compromised checkout code and transaction abuse as distinct problems.'],caveats=['Risk scores and malware scans have different scopes and neither proves an order is legitimate.'])
edit('ae6860d26daf50fbd2fa048d',2,title='Use unique admin credentials, MFA and compromise-driven password changes',summary='Reduce store account takeover with unique credentials, stronger authentication and prompt revocation.',steps=['Use long unique passwords managed in a password manager and enable strong MFA or passkeys where supported.','Block known-compromised passwords where the identity system supports it.','Change credentials when compromise is suspected or confirmed; do not adopt the source\'s arbitrary 60-90-day user-password rotation as a universal requirement.','Revoke access, sessions and tokens during offboarding rather than waiting for a password change.','Review login alerts and maintain a secure account-recovery process.'],caveats=['This updates the source\'s rotation advice using current NIST guidance; service credentials may need a separate lifecycle policy.'])
edit('927e3c057c140fa4066d0614',2,summary='Track disputes using the processor\'s actual definitions and thresholds instead of copying a fixed chargeback percentage.',steps=['Obtain current monitoring definitions, thresholds, periods and consequences from the processor or acquirer.','Calculate the relevant metrics on the correct denominator; different programs can count disputes and transactions differently.','Set internal alerts early enough to investigate fraud, delivery and customer-service causes.','Evaluate authentication, review routing and evidence collection while monitoring legitimate-order declines.','Confirm coverage conditions before relying on any chargeback-protection program.'],caveats=['The source\'s 0.9%, 1% and average loss figures are not universal current thresholds or guarantees.'])
edit('927e3c057c140fa4066d0614',6,title='Confirm merchant PCI scope with the acquirer and payment setup',summary='Determine the store\'s actual payment-data responsibilities and validation route even on a hosted platform.',steps=['Map where payment data is captured, processed and stored, including apps and customer support.','Ask the acquirer or payment brand which validation route and SAQ eligibility apply to the actual environment.','Do not infer the required assessment from a universal 20,000-transaction rule.','Confirm the hosted provider\'s scope and retain responsibility for merchant accounts, integrations and handling practices outside that scope.','Keep payment data out of support messages, order notes and spreadsheets; use approved payment collection flows.'],caveats=['Platform compliance does not automatically validate every merchant workflow; requirements depend on the actual environment.'])
r=read(DEST/'results/927e3c057c140fa4066d0614.json')['cards'][3];s=r['steps'];s[0]='Configure the supported 3DS flow according to processor requirements and applicable authentication rules; frictionless and challenge outcomes are not simply low-risk versus high-risk switches.';edit('927e3c057c140fa4066d0614',3,steps=s)
edit('627680c63980cf37fee4be82',13,summary='Compare what an agent credential actually proves and where authorization is enforced before adopting an emerging protocol.',steps=['Separate agent identity, represented user or merchant, and permission to perform the requested action.','Ask vendors to demonstrate current supported issuers, validation, revocation, audience binding and replay protection.','Test whether a valid identity can be denied an out-of-scope action, including an action against another store\'s data.','Confirm interoperability using the actual implementation rather than announcement-level support lists.','Document fallback and credential-expiry behavior before enabling payment or account-changing operations.'],caveats=['Protocol names and partnerships in the source are unverified snapshots; no vendor support or universal interoperability is assumed.'])
r=read(DEST/'results/627680c63980cf37fee4be82.json')['cards'][6];s=r['steps'];s[1]='Treat input filtering as one signal; enforce action permissions and business rules outside the model even when the prompt or retrieved content is malicious.';edit('627680c63980cf37fee4be82',6,steps=s)
edit('c2f4e7d1e785c991bf0d5f3f',3,title='Prevent storefront XSS with context-aware rendering',summary='Keep customer-supplied content as data using safe rendering, appropriate encoding and sanitization.',steps=['Trace untrusted product reviews, profile fields, search parameters and imported content to their rendering locations.','Use framework auto-escaping and safe text APIs for plain text; encode at output for the actual context.','Do not apply HTML entity encoding as a universal solution for JavaScript, CSS or URL contexts; avoid inserting untrusted data in executable contexts.','Where rich HTML is required, use a maintained sanitizer with a restricted policy.','Add a tested CSP as defense in depth and validate harmless stored/reflected cases on an owned test environment.'],caveats=['CSP and escaping are complementary; neither replaces authorization or secures every injection context alone.'])
write(DEST/'security-review-log.json',changes)
print({'changes':len(changes)})
